// Exnoria - onb.contact.nudge
// Branch on cause_code to select message template

const webhook = $("Webhook").first().json.body;
const contact = $input.first().json;

const { contact_id, signal_id, cause_code, interventions } = webhook;

const firstname = contact.properties?.firstname?.value ?? 'there';
const email     = contact.properties?.email?.value     ?? '';
const phone     = contact.properties?.phone?.value     ?? '';

const cleanPhone = phone.replace(/[^\d]/g, '');

let message = '';

if (cause_code === 'ONB-FRC') {
  // ONB_FRC_01 — abandoned setup
  message = [
    'Hi ' + firstname + ',',
    '',
    'We noticed you haven\'t completed your setup yet — and we want to make sure you get the most out of your account.',
    '',
    'It only takes a few minutes to finish. Click here to pick up where you left off:',
    '[Setup Link]',
    '',
    'If you ran into any issues, just reply to this message and we\'ll help you out.',
    '',
    '-- Exnoria Onboarding Team'
  ].join('\n');
} else if (cause_code === 'ONB-CLR') {
  // ONB_CLR_01 — confused about next steps
  message = [
    'Hi ' + firstname + ',',
    '',
    'Here\'s a quick reminder of your next onboarding steps:',
    '',
    '1. Complete your profile setup',
    '2. Connect your first integration',
    '3. Run your first workflow',
    '',
    'Need help? Check out our getting started guide: [Guide Link]',
    '',
    '-- Exnoria Onboarding Team'
  ].join('\n');
} else {
  message = 'Hi ' + firstname + ', we noticed your onboarding may need a boost. Reply if you need help!';
}

const whatsapp_payload = cleanPhone ? {
  messaging_product: 'whatsapp',
  to: cleanPhone,
  type: 'text',
  text: { body: message }
} : null;

const nudgedAt = new Date(new Date().setUTCHours(0,0,0,0)).getTime();

return [{
  json: {
    contact_id,
    signal_id,
    cause_code,
    email,
    firstname,
    phone: cleanPhone,
    whatsapp_payload,
    message_template: cause_code === 'ONB-FRC' ? 'abandoned_setup' : cause_code === 'ONB-CLR' ? 'next_steps_checklist' : 'generic_nudge',
    nudged_at: nudgedAt
  }
}];

